async function listTrial(){
 const rows=history(),data={sv_usuarios:{a:{uid:'a',nombre:'Persona a',rol:'administrativo'},b:{uid:'b',nombre:'Persona b',rol:'administrativo'}},sv_chat_roles:{a:{rol:'administrativo',activo:true},b:{rol:'administrativo',activo:true}},sv_permisos:{administrativo:{indiceVersion:2,indiceModulos:{venta:true,detalle:true,presupuesto:true}}},sisventas:{ventas:rows}},reports=[];
 for(const scopedReads of [false,true]){
  const db=memoryDB(data),base=db.ref.bind(db),calls=[];
  function measured(path,value,query){calls.push({path,query,rows:value&&typeof value==='object'?Object.keys(value).length:0,bytes:Buffer.byteLength(JSON.stringify(value))});return{val:()=>structuredClone(value)};}
  db.ref=path=>({get:async()=>measured(path,(await base(path).get()).val(),false),orderByChild:field=>({equalTo:value=>({get:async()=>measured(path,Object.fromEntries(Object.entries((await base(path).get()).val()||{}).filter(([,row])=>(row[field]??null)===value)),true)})})});
  const api=createCommercialOwnership({db,auth:{verifyIdToken:async()=>({uid:'a'})},enabled:true,scopedReads,queryReader:async(p,field,value)=>(await db.ref(p).orderByChild(field).equalTo(value).get()).val()}),result=await api.list(await api.authorize({headers:{authorization:'Bearer fictitious'}},'ventas'));
  reports.push({records:result.records,rows:calls.filter(c=>c.path==='sisventas/ventas').reduce((n,c)=>n+c.rows,0),bytes:calls.reduce((n,c)=>n+c.bytes,0),calls:calls.length});
 }
 if(canonical(reports[0].records)!==canonical(reports[1].records))throw Error('La proyección cambió');
 return{before:{rows:reports[0].rows,bytes:reports[0].bytes,calls:reports[0].calls},after:{rows:reports[1].rows,bytes:reports[1].bytes,calls:reports[1].calls},visible:Object.keys(reports[1].records).length,equivalent:true};
}
async function lockTrial(){
 let data={sv_labor_config:{ready:true,schema:1}},acquires=0,commits=0;
 const store={read:async p=>child(data,parts(p)),acquire:async lease=>{if(data.sv_labor_guard||data.sv_labor_receipts?.[lease.opId])throw Object.assign(Error('Not available'),{statusCode:403});acquires++;data.sv_labor_guard=structuredClone(lease);},commit:async(patch,lease)=>{if(data.sv_labor_guard?.fence!==lease.fence)throw Error('Fence cambió');commits++;for(const [p,v]of Object.entries(patch))data=put(data,parts(p),v);},abort:async lease=>{if(data.sv_labor_guard?.fence===lease.fence)delete data.sv_labor_guard;}};
 const guard=createLaborGuard({store}),actor={uid:'demo',mode:'user',opId:'confirmed-demo-attempt',operation:'fixture',input:{demo:true}};await guard.run(actor,async()=>({ok:true,committed:true}));
 let release,entered,active=false;const gate=new Promise(r=>release=r),started=new Promise(r=>entered=r);
 const pending=guard.run({uid:'demo',mode:'command',role:'admin',permissionDigest:digest({}),operation:'independent-fixture'},async()=>{active=true;entered();await gate;active=false;return{ok:true};});await started;
 const beforeAcquires=acquires,beforeCommits=commits;const timeout=setTimeout(release,1500);
 try{const result=await guard.run(actor,()=>{throw Error('Intento repetido');});return{confirmed:result.committed===true,whileOtherActive:active,newLeases:acquires-beforeAcquires,newCommits:commits-beforeCommits};}
 finally{clearTimeout(timeout);release();await pending;}
}
const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SisVentas · auditoría local</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1321;color:#e6edf8;font:15px system-ui}header{background:#101c2e;padding:20px 5%;border-bottom:1px solid #30425c}main{max-width:1100px;margin:28px auto;padding:0 20px}h1{font-size:26px}h2{font-size:19px}p,small{color:#aabbd1;line-height:1.5}.panel{background:#142137;border:1px solid #334865;border-radius:16px;padding:24px;margin:20px 0}button{background:#e7f0ff;color:#132440;border:0;border-radius:9px;padding:12px 18px;font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #8ab2f4;outline-offset:3px}button:disabled{opacity:.7;cursor:default}.metrics{display:flex;gap:28px;flex-wrap:wrap;margin:20px 0}.metrics b{display:block;color:#8bdb98;font-size:25px;margin-top:5px}.status{min-height:26px;margin-top:18px}.spin{display:inline-block;width:15px;height:15px;border:2px solid #829bc1;border-top-color:transparent;border-radius:50%;animation:spin .8s linear infinite;margin-right:8px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:500px){.panel{padding:18px}.metrics{gap:20px}button{width:100%}}</style><header>SisVentas · <small>Prueba local con datos ficticios</small></header><main><h1>Lecturas y confirmaciones más livianas</h1><p>Se ejecutan los módulos reales del servidor contra datos de ejemplo. Este ensayo no se conecta a Firebase ni guarda operaciones reales.</p><section class="panel"><h2>Consultar mis ventas</h2><p>El listado consulta por responsable y conserva la resolución de los registros antiguos.</p><button id="list" data-action="list">Comparar lecturas</button><div class="status" id="list-status" role="status">Listo para comparar.</div><div class="metrics" id="list-result"></div></section><section class="panel"><h2>Comprobar un guardado ya confirmado</h2><p>La confirmación propia puede responder mientras otro guardado está ocupado. Los nuevos guardados conservan su protección.</p><button id="lock" data-action="lock">Probar confirmación</button><div class="status" id="lock-status" role="status">Listo para probar.</div><div class="metrics" id="lock-result"></div></section><small>Los conteos pertenecen al ejemplo. No representan tiempos ni facturación de producción. No se publicaron cambios.</small></main><script>
for(const button of document.querySelectorAll('[data-action]'))button.onclick=async()=>{const action=button.dataset.action,status=document.getElementById(action+'-status'),out=document.getElementById(action+'-result'),label=button.textContent;button.disabled=true;button.innerHTML='<span class="spin" aria-hidden="true"></span>Comprobando…';status.textContent='Ejecutando prueba ficticia…';try{const response=await fetch('/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});const data=await response.json();if(!response.ok)throw Error(data.message);if(action==='list'){status.textContent='Los mismos '+data.visible+' registros visibles, sin descargar ventas ajenas.';out.innerHTML='<div><small>Filas de ventas leídas antes</small><b>'+data.before.rows+'</b></div><div><small>Filas leídas ahora</small><b>'+data.after.rows+'</b></div><div><small>Resultado idéntico</small><b>Sí</b></div>';const detail=document.createElement('p');detail.textContent='Transferencia del ejemplo: '+data.before.bytes+' → '+data.after.bytes+' bytes. Consultas: '+data.before.calls+' → '+data.after.calls+'.';out.append(detail);}else{if(!data.whileOtherActive||!data.confirmed)throw Error('La confirmación esperó al otro guardado');status.textContent='Confirmado sin esperar al guardado independiente.';out.innerHTML='<div><small>Nuevos bloqueos</small><b>'+data.newLeases+'</b></div><div><small>Escrituras repetidas</small><b>'+data.newCommits+'</b></div>';}}catch(e){status.textContent=e.message;}finally{button.disabled=false;button.textContent=label;}};
</script></html>`;
async function start(port=0){const server=http.createServer(async(req,res)=>{try{if(req.method==='GET'&&req.url==='/'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'"});return res.end(html);}if(req.method==='POST'&&req.url==='/demo'){let body='';for await(const chunk of req){body+=chunk;if(body.length>1024)throw Error('Petición inválida');}const {action}=JSON.parse(body),result=action==='list'?await listTrial():action==='lock'?await lockTrial():null;if(!result)throw Error('Acción inválida');res.writeHead(200,{'Content-Type':'application/json','Cache-Control':'no-store'});return res.end(JSON.stringify(result));}res.writeHead(404);res.end();}catch(e){res.writeHead(400,{'Content-Type':'application/json'});res.end(JSON.stringify({message:e.message}));}});await new Promise(r=>server.listen(port,'127.0.0.1',r));return{server,url:'http://127.0.0.1:'+server.address().port+'/'};}
module.exports={start,listTrial,lockTrial};if(require.main===module)start(Number(process.argv[2]||8896)).then(x=>process.stdout.write(x.url+'\n'));
